export function slugifyMenuName(name: string): string {
  return (name || '')
    .toLowerCase()
    .trim()
    .replace(/['']/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function localMenuImage(name?: string, imageUrl?: string): ImageSourcePropType | undefined {
  if (imageUrl) {
    const m = imageUrl.match(/\/images\/menu\/([^./]+)(?:\.[a-z]+)?/i);
    if (m && MENU_IMAGE_BY_SLUG[m[1]]) return MENU_IMAGE_BY_SLUG[m[1]];
  }
  if (name) {
    const slug = slugifyMenuName(name);
    if (MENU_IMAGE_BY_SLUG[slug]) return MENU_IMAGE_BY_SLUG[slug];
  }
  return undefined;
}
